            schema_version: 1;
            /** @description Monotonic write counter. Every Plan pins the generation it was computed against; execution re-validates after taking the locks and answers 409 `plan_stale` if it moved. */
            generation: number;
            /** @description RFC 3339 UTC of the last write. */
            updated_at: string;
            /** @description Principal of the last write (`key:<label>`, `bvbrc:<user>`, `local:<uid>`), plus `sudo_user` when the CLI saw one, joined as `principal[/sudo_user]`. */
            updated_by: string;
            rag_root: components["schemas"]["AbsPath"];
            port_base: number;
            port_stride: number;
            /** @description Gateway landing-page order. Every entry names a tenant in `tenants`; `admin` is never listed (the gateway renderer filters it anyway). */
            display_order: components["schemas"]["TenantName"][];
