                    tag: string;
                    worktree: components["schemas"]["AbsPath"];
                    ui_dist: components["schemas"]["AbsPath"];
                    python_env: components["schemas"]["AbsPath"];
                    prepared_at: components["schemas"]["Timestamp"];
